const categorias = [
  {
    categoria: "chokepoint_judicial",
    patterns: ["P01","P02","P03","P03-A","P03-B"],
    query: '"liminar monocrática" STF OR "habeas corpus concedido" OR "suspende investigação" ministro'
  },
  {
    categoria: "operacao_policial",
    patterns: ["P02","P05","P07","P08","P09","P10"],
    query: '"operação da Polícia Federal" lavagem OR GAECO facção OR "operação" PCC fintech'
  },
  {
    categoria: "ato_legislativo",
    patterns: ["P05","P06-B","P09","P11"],
    query: '"CPI" "sem relatório" OR "emenda parlamentar" sigilo OR "orçamento secreto" Congresso'
  },
  {
    categoria: "mecanismo_sistemico",
    patterns: ["P07","P10","P11"],
    query: '"consignado INSS" desconto indevido OR "dívida pública" custeio Selic'
  },
  {
    categoria: "incidente_diplomatico",
    patterns: ["P04","P09"],
    query: 'sanção OFAC Brasil OR "extradição" ministro OR "visto cassado" Brasil EUA'
  },
  {
    categoria: "perseguicao_processual",
    patterns: ["P02","P04","P04b"],
    query: '"investigador" processado OR delator ameaçado OR auditor exonerado Brasil'
  },
  {
    categoria: "abuso_processual",
    patterns: ["P01","P03","P06"],
    query: '"prisão preventiva" "excesso de prazo" OR "substituição" defesa compulsória'
  }
];

return categorias.map(c => ({ json: c }));

const cat = $('Loop Categorias').item.json.categoria;
const patterns = $('Loop Categorias').item.json.patterns;

let rawItems = $json.rss && $json.rss.channel && $json.rss.channel[0] && $json.rss.channel[0].item
  ? $json.rss.channel[0].item : [];
if (!Array.isArray(rawItems)) rawItems = [rawItems];

const staticData = $getWorkflowStaticData('global');
if (!staticData.urlsVistas) staticData.urlsVistas = [];
const vistos = new Set(staticData.urlsVistas);

const cutoff = Date.now() - 1000*60*60*48; // últimas 48h
const out = [];

for (const it of rawItems.slice(0, 8)) {
  const link = Array.isArray(it.link) ? it.link[0] : it.link;
  const title = Array.isArray(it.title) ? it.title[0] : it.title;
  const pubDateRaw = Array.isArray(it.pubDate) ? it.pubDate[0] : it.pubDate;
  const pubDate = pubDateRaw ? new Date(pubDateRaw) : null;
  const desc = Array.isArray(it.description) ? it.description[0] : (it.description || '');
  const source = it.source && it.source[0] && it.source[0]._ ? it.source[0]._ : '';

  if (!link || vistos.has(link)) continue;
  if (pubDate && pubDate.getTime() < cutoff) continue;

  out.push({
    categoria: cat,
    patterns,
    title,
    link,
    pubDate: pubDateRaw,
    outlet: source,
    snippet: String(desc).replace(/<[^>]+>/g, '').slice(0, 600)
  });
  staticData.urlsVistas.push(link);
}
// mantém o set de URLs vistas com tamanho controlado
if (staticData.urlsVistas.length > 4000) {
  staticData.urlsVistas = staticData.urlsVistas.slice(-2000);
}

return out.map(o => ({ json: o }));

const raw = $json.content && $json.content[0] && $json.content[0].text ? $json.content[0].text : '';
let parsed;
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  return []; // resposta não-parseável -> descarta silenciosamente, log fica no execution do n8n
}
if (parsed.decisao !== 'candidato') return [];

const origem = $('Extrair Itens + Dedupe (48h)').item.json;
parsed._origem = {
  link: origem.link,
  outlet: origem.outlet,
  pubDate: origem.pubDate,
  categoria: origem.categoria
};
return [{ json: parsed }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.candidatosFase1) staticData.candidatosFase1 = [];
staticData.candidatosFase1.push($json);
return [{ json: { ok: true, acumulados: staticData.candidatosFase1.length } }];

const staticData = $getWorkflowStaticData('global');
const candidatos = staticData.candidatosFase1 || [];
return candidatos.map(c => ({ json: c }));

const cand = $('Loop Candidatos (Corroboração)').item.json;

let rawItems = $json.rss && $json.rss.channel && $json.rss.channel[0] && $json.rss.channel[0].item
  ? $json.rss.channel[0].item : [];
if (!Array.isArray(rawItems)) rawItems = [rawItems];

function hostOf(url) {
  try { return new URL(url).hostname.replace('www.', ''); } catch(e) { return url; }
}

const origemHost = hostOf(cand._origem.link);
const fontesIndependentes = [];
for (const it of rawItems.slice(0, 6)) {
  const link = Array.isArray(it.link) ? it.link[0] : it.link;
  const title = Array.isArray(it.title) ? it.title[0] : it.title;
  const pubDateRaw = Array.isArray(it.pubDate) ? it.pubDate[0] : it.pubDate;
  const source = it.source && it.source[0] && it.source[0]._ ? it.source[0]._ : hostOf(link);
  if (!link) continue;
  if (hostOf(link) === origemHost) continue; // mesma fonte da original, não conta
  fontesIndependentes.push({ title, url: link, outlet: source, date: pubDateRaw ? new Date(pubDateRaw).toISOString().slice(0,10) : null });
}

const sources = [
  { title: cand.title, url: cand._origem.link, outlet: cand._origem.outlet, date: cand._origem.pubDate ? new Date(cand._origem.pubDate).toISOString().slice(0,10) : null },
  ...fontesIndependentes.slice(0, 2)
];

const evidence_status = fontesIndependentes.length > 0
  ? "ev-alleged"  // NUNCA promover a ev-confirmed automaticamente — apenas sinalizar candidatura via flag abaixo
  : "ev-alleged";

const possivel_ev_confirmed = fontesIndependentes.length > 0;

const finalObj = {
  id: null,
  _nota_id: "PENDENTE — atribuir apenas após consultar claude.ai-corpus-ids-sync.json ao vivo. Nunca reutilizar ou estimar.",
  date: cand.date || null,
  date_precision: cand.date_precision || "day",
  title: cand.title,
  summary: cand.summary,
  category: cand.category,
  actors: cand.actors || [],
  institutions: cand.institutions || [],
  legal_basis: [],
  patterns: cand.patterns || [],
  evidence_status: evidence_status,
  _flag_possivel_ev_confirmed: possivel_ev_confirmed,
  _flag_motivo: possivel_ev_confirmed
    ? `${fontesIndependentes.length} fonte(s) independente(s) localizada(s) automaticamente — VERIFICAR MANUALMENTE o conteúdo (não apenas o título) antes de promover a ev-confirmed.`
    : "nenhuma fonte independente localizada na busca automática — permanece ev-alleged até verificação manual.",
  sources: sources,
  result: cand.result || "",
  connections: [],
  status: "documentado",
  lacuna_investigativa: cand.lacuna_investigativa || null,
  ponto_de_inflexao: cand.ponto_de_inflexao || null,
  analise: cand.analise || null
};

return [{ json: finalObj }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.candidatosFinais) staticData.candidatosFinais = [];
staticData.candidatosFinais.push($json);
return [{ json: { ok: true } }];

const staticData = $getWorkflowStaticData('global');
const candidatos = staticData.candidatosFinais || [];

const hoje = new Date().toISOString().slice(0, 10);
const lote = {
  _tipo: "lote_candidatos_triagem_automatica",
  _aviso: "Gerado por agente n8n. NENHUM item aqui é ev-confirmed por definição do pipeline. IDs não atribuídos — usar merge_todo_pending.py com claude.ai-corpus-ids-sync.json vivo. Revisão manual obrigatória antes de qualquer merge em lawfare.json.",
  data_execucao: hoje,
  total_candidatos: candidatos.length,
  por_categoria: candidatos.reduce((acc, c) => { acc[c.category] = (acc[c.category]||0)+1; return acc; }, {}),
  candidatos: candidatos
};

// limpa acumuladores para a próxima execução diária (mantém urlsVistas para dedupe contínuo)
staticData.candidatosFase1 = [];
staticData.candidatosFinais = [];

const buffer = Buffer.from(JSON.stringify(lote, null, 2), 'utf-8');

return [{
  json: { total_candidatos: lote.total_candidatos, data_execucao: hoje },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'application/json',
      fileName: `candidatos-triagem-${hoje}.json`
    }
  }
}];
